Q: Dev launcher setup that initializes twice on Android React Native app startup causes crash A: <p>the same mistake in Expo 52.0.47.</p>
<p>The fix in MainApplication.kt :</p>
<pre><code>class MainApplication : Application(), ReactApplication,
  NotificationManager.NotificationLaunchIntentProvider,
  NotificationManager.NotificationChannelIdProvider {

  //Add this:
  companion object {
    @Volatile
    private var expoLifecycleInitialized = false
  }

  override val reactNativeHost: ReactNativeHost = ReactNativeHostWrapper(
        this,
        object : DefaultReactNativeHost(this) {
          override fun getPackages(): List&lt;ReactPackage&gt; {
            val packages = PackageList(this).packages
            // Packages that cannot be autolinked yet can be added manually here, for example:
            // packages.add(new MyReactNativePackage());
            return packages
          }

          override fun getJSMainModuleName(): String = &quot;.expo/.virtual-metro-entry&quot;

          override fun getUseDeveloperSupport(): Boolean = BuildConfig.DEBUG

          override val isNewArchEnabled: Boolean = BuildConfig.IS_NEW_ARCHITECTURE_ENABLED
          override val isHermesEnabled: Boolean = BuildConfig.IS_HERMES_ENABLED
      }
  )

  override val reactHost: ReactHost
    get() = ReactNativeHostWrapper.createReactHost(applicationContext, reactNativeHost)

  override fun onCreate() {
    super.onCreate()
    SoLoader.init(this, OpenSourceMergedSoMapping)
    if (BuildConfig.IS_NEW_ARCHITECTURE_ENABLED) {
      // If you opted-in for the New Architecture, we load the native entry point for this app.
      load()
    }
    //And add this:
    if (!expoLifecycleInitialized) {
      try {
        ApplicationLifecycleDispatcher.onApplicationCreate(this)
        expoLifecycleInitialized = true
      } catch (error: IllegalStateException) {
        if (error.message?.contains(&quot;DevelopmentClientController was initialized.&quot;) == true) {
          Log.w(&quot;MainApplication&quot;, &quot;DevLauncher already initialized, skipping duplicate init&quot;)
          expoLifecycleInitialized = true
        } else {
          throw error
        }
      }
    }
</code></pre>
